diff --git a/test.js b/test.js
index e303a46..ac31425 100644
--- a/test.js
+++ b/test.js
@@ -193,6 +193,35 @@ test('clearQueue', async t => {
 	t.is(limit.pendingCount, 0);
 });

+test('clearQueue with default options leaves the active promise untouched and clears all queued functions', async t => {
+	const limit = pLimit(1);
+	let queuedRan = false;
+
+	const activePromise = limit(async () => {
+		await delay(50);
+		return 'active result';
+	});
+
+	const queuedPromises = Array.from({length: 3}, () => limit(() => {
+		queuedRan = true;
+	}));
+
+	await Promise.resolve();
+	t.is(limit.activeCount, 1);
+	t.is(limit.pendingCount, 3);
+
+	limit.clearQueue();
+
+	t.is(limit.pendingCount, 0);
+	t.is(limit.activeCount, 1);
+
+	t.is(await activePromise, 'active result');
+	t.false(queuedRan);
+
+	// The cleared queued promises never settle, so we don't await them here.
+	t.true(queuedPromises.every(promise => promise instanceof Promise));
+});
+
 // Node.js 20 has a bug where DOMException is not properly handled by AVA's `throwsAsync`.
 const testClearQueueRejects = process.versions.node.startsWith('20.') ? test.skip : test;
